// const — cannot be reassigned
const name = 'Alice';
const PI = 3.14159;

// let — can be reassigned
let score = 0;
score = score + 10; // OK

// The seven data types
const str    = 'Hello!';        // String
const num    = 42;              // Number
const float  = 3.14;           // Number (no separate float type)
const bool   = true;            // Boolean
const nothing = null;           // Null (intentional empty)
let  undef;                    // Undefined (declared but not assigned)
const sym    = Symbol('id');    // Symbol (unique identifier)

// typeof operator
console.log(typeof 'hello');    // 'string'
console.log(typeof 42);         // 'number'
console.log(typeof true);       // 'boolean'
console.log(typeof null);       // 'object' (famous JS bug!)
console.log(typeof undefined);  // 'undefined'

// Arithmetic
console.log(10 + 3);   // 13
console.log(10 - 3);   // 7
console.log(10 * 3);   // 30
console.log(10 / 3);   // 3.333...
console.log(10 % 3);   // 1  (remainder/modulus)
console.log(2 ** 10);  // 1024 (exponentiation)

// String concatenation & template literals
const greet = 'Hello, ' + 'World!';     // old way
const name = 'Alice';
const score = 95;
const msg = `Hi ${name}, your score is ${score}!`; // modern

// Comparison (always use === not ==)
console.log(5 === 5);    // true  (strict equality)
console.log(5 === '5');  // false (different types)
console.log(5 == '5');   // true  (loose equality — AVOID)
console.log(5 !== 3);    // true
console.log(5 > 3);      // true
console.log(5 >= 5);     // true

// Logical
console.log(true && false);  // false (AND)
console.log(true || false);  // true  (OR)
console.log(!true);          // false (NOT)

// Ternary operator: condition ? valueIfTrue : valueIfFalse
const status = score >= 90 ? 'Excellent' : 'Good';

const score = 72;

// if / else if / else
if (score >= 90) {
  console.log('A');
} else if (score >= 80) {
  console.log('B');
} else if (score >= 70) {
  console.log('C');
} else {
  console.log('Needs improvement');
}

// switch
const day = 'Monday';
switch (day) {
  case 'Monday':
  case 'Tuesday':
    console.log('Weekday');
    break;
  case 'Saturday':
  case 'Sunday':
    console.log('Weekend');
    break;
  default:
    console.log('Unknown day');
}

// for loop
for (let i = 0; i < 5; i++) {
  console.log(i); // 0 1 2 3 4
}

// while loop
let count = 0;
while (count < 3) {
  console.log(count);
  count++;
}

// for...of — iterate array values
const fruits = ['apple', 'banana', 'cherry'];
for (const fruit of fruits) {
  console.log(fruit);
}

// for...in — iterate object keys
const user = { name: 'Alice', age: 25 };
for (const key in user) {
  console.log(`${key}: ${user[key]}`);
}

const nums = [3, 1, 4, 1, 5, 9, 2, 6];

// Access
console.log(nums[0]);       // 3 (first)
console.log(nums.at(-1));   // 6 (last — modern)
console.log(nums.length);   // 8

// Mutation methods
nums.push(7);              // add to end
nums.pop();                // remove from end
nums.unshift(0);           // add to start
nums.shift();              // remove from start
nums.splice(2, 1);         // remove 1 element at index 2

// Non-mutation (return new array)
const doubled = nums.map(n => n * 2);
const evens   = nums.filter(n => n % 2 === 0);
const sum     = nums.reduce((acc, n) => acc + n, 0);
const found   = nums.find(n => n > 5);   // first match
const hasNine = nums.some(n => n === 9); // any match?
const allPos  = nums.every(n => n > 0);  // all match?

// Spread, concat, slice
const copy    = [...nums];
const joined  = [...nums, ...doubled];
const sliced  = nums.slice(0, 3); // [3,1,4]

// Object literal
const user = {
  id: 1,
  name: 'Alice',
  email: 'alice@example.com',
  scores: [95, 87, 92],
  // Method shorthand
  greet() {
    return `Hi, I'm ${this.name}`;
  }
};

// Access
console.log(user.name);          // 'Alice'
console.log(user['email']);      // 'alice@example.com'
console.log(user.greet());       // 'Hi, I'm Alice'

// Destructuring
const { name, email, scores } = user;
const { name: displayName } = user;  // rename
const { id = 0 } = user;            // with default

// Spread — shallow copy / merge
const updated = { ...user, name: 'Bob' };
const merged  = { ...user, ...{ role: 'admin' } };

// Object methods
const keys   = Object.keys(user);    // ['id','name','email',...]
const values = Object.values(user);  // [1,'Alice','alice@...',...]
const entries = Object.entries(user); // [[key,val],...]
const clone  = Object.assign({}, user);
